// Status: Assistant state. Sequence, progress, kind and text stay in the layout.
type protoStatus struct {
	// retired state sequence
	seq   uint32
	state uint8
	// retired progress percent
	progress uint8
	// retired prompt kind
	kind uint8
	// retired detail text
	text string
}

const protoStatusFixedSize = 9
const protoStatusseqOff = 0
const protoStatusstateOff = 4
const protoStatusprogressOff = 5
const protoStatuskindOff = 6
const protoStatustextOff = 7

func (m protoStatus) encode() []byte {
	s0 := ""
	if len(s0) > 65535 {
		s0 = s0[:65535]
	}
	b := make([]byte, 0, protoStatusFixedSize)
	b = binary.LittleEndian.AppendUint32(b, 0)
	b = append(b, m.state)
	b = append(b, 0)
	b = append(b, 0)
	b = binary.LittleEndian.AppendUint16(b, uint16(len(s0)))
	b = append(b, s0...)
	return b
}

func decodeProtoStatus(b []byte) (protoStatus, bool) {
	var m protoStatus
	if len(b) < protoStatusFixedSize {
		return m, false
	}
	m.seq = binary.LittleEndian.Uint32(b[protoStatusseqOff : protoStatusseqOff+4])
	m.state = b[protoStatusstateOff]
	m.progress = b[protoStatusprogressOff]
	m.kind = b[protoStatuskindOff]
	off := protoStatusFixedSize
	n0 := int(binary.LittleEndian.Uint16(b[protoStatustextOff : protoStatustextOff+2]))
	if off+n0 > len(b) {
		return m, false
	}
	m.text = string(b[off : off+n0])
	off += n0
	return m, true
}

